package io.floci.aws.services.athena;

import com.fasterxml.jackson.databind.JsonNode;
import io.floci.aws.core.common.RequestConstraintCheck;

/** Checks Athena requests against the constraints generated by {@code tools/aws/regen_athena_shapes.py}. */
final class AthenaRequestShapes {

    private static final RequestConstraintCheck CHECK = RequestConstraintCheck.load(
            "aws/athena-request-shapes.json", "Athena request shapes",
            RequestConstraintCheck.standardMessages("InvalidRequestException"));

    private AthenaRequestShapes() {
    }

    static void check(String operation, JsonNode request) {
        if (CHECK.hasOperation(operation)) {
            CHECK.check(operation, request);
        }
    }
}
